CREATE POLICY "communication_names" ON "people" AS PERMISSIVE FOR SELECT TO "sep_runtime" USING (current_setting('sep.communication_staff',true)='true' AND EXISTS(SELECT 1 FROM event_notifications n WHERE n.organization_id=nullif(current_setting('sep.organization_id',true),'')::uuid AND n.event_id=nullif(current_setting('sep.event_id',true),'')::uuid AND n.person_id="people"."id"));